import {test} from 'node:test';import assert from 'node:assert/strict';import {startM2Fixture} from './fixture.mjs';import {Client} from '@modelcontextprotocol/sdk/client/index.js';import {StreamableHTTPClientTransport} from '@modelcontextprotocol/sdk/client/streamableHttp.js';import {SSEClientTransport} from '@modelcontextprotocol/sdk/client/sse.js';import {createHash} from 'node:crypto';
test('controlled fixture performs actual HTTP and SSE SDK handshakes',async()=>{const f=await startM2Fixture({allowedOrigin:'http://localhost:3000'});try{for(const [path,T]of [['/mcp',StreamableHTTPClientTransport],['/sse',SSEClientTransport]]){const c=new Client({name:'fixture-test',version:'1'});try{await c.connect(new T(new URL(path,f.origin)));assert.equal(c.getServerVersion().name,'m2-controlled-fixture');}finally{await c.close();}}assert.equal(f.stats.httpInitialize,1);assert.equal(f.stats.sseInitialize,1);}finally{await f.close();}});
test('OAuth fixture enforces PKCE resource and one-time code redemption',async()=>{const app='http://localhost:3000',f=await startM2Fixture({allowedOrigin:app});try{const verifier='synthetic-verifier-43-characters-for-fixture0',auth=new URL('/authorize',f.origin);for(const [k,v]of Object.entries({client_id:'public',response_type:'code',redirect_uri:app+'/oauth/callback',state:'synthetic-state',code_challenge:createHash('sha256').update(verifier).digest('base64url'),code_challenge_method:'S256',resource:f.origin+'/oauth-mcp',scope:'read'}))auth.searchParams.set(k,v);const r=await fetch(auth,{redirect:'manual'});assert.equal(r.status,302);const callback=new URL(r.headers.get('location'));const body=new URLSearchParams({client_id:'public',grant_type:'authorization_code',code:callback.searchParams.get('code'),redirect_uri:app+'/oauth/callback',code_verifier:verifier,resource:f.origin+'/oauth-mcp'}).toString();const request=()=>fetch(f.origin+'/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});assert.equal((await request()).status,200);assert.equal((await request()).status,400);assert.equal(f.stats.pkceVerified,1);assert.equal(f.stats.resourceVerified,1);assert.equal(f.stats.oauthReplays,1);}finally{await f.close();}});
test('OAuth deny endpoint advertises its own resource and performs real authorization denial',async()=>{const app='http://localhost:3000',f=await startM2Fixture({allowedOrigin:app});try{const challenge=await fetch(f.origin+'/oauth-deny-mcp');assert.equal(challenge.status,401);assert.match(challenge.headers.get('www-authenticate'),/scope="deny"/u);const metadata=await fetch(f.origin+'/.well-known/oauth-protected-resource/oauth-deny-mcp').then(r=>r.json());assert.equal(metadata.resource,f.origin+'/oauth-deny-mcp');const auth=new URL('/authorize',f.origin);for(const [k,v]of Object.entries({client_id:'public',response_type:'code',redirect_uri:app+'/oauth/callback',state:'s',code_challenge:'synthetic',code_challenge_method:'S256',resource:metadata.resource,scope:'deny'}))auth.searchParams.set(k,v);const response=await fetch(auth,{redirect:'manual'});assert.equal(response.status,302);assert.equal(new URL(response.headers.get('location')).searchParams.get('error'),'access_denied');const stats=await fetch(f.origin+'/stats').then(r=>r.json());assert.equal(stats.oauthDenials,1);assert(Object.values(stats).every(n=>typeof n==='number'));}finally{await f.close();}});
test('fixture can advertise localhost while binding only loopback, avoiding platform-host Cookie scope',async()=>{const f=await startM2Fixture({allowedOrigin:'https://127.0.0.1:3000',publicHostname:'localhost'});try{assert.equal(new URL(f.origin).hostname,'localhost');assert.equal((await fetch(f.origin+'/stats')).status,200);assert.equal(f.stats.cookieRequests,0);}finally{await f.close();}});
test('controlled fixture serves actual paginated HTTP and SSE SDK tool catalogs with numeric counters only',async()=>{
 const f=await startM2Fixture({allowedOrigin:'http://localhost:3000'});try{
  for(const [path,T]of [['/mcp',StreamableHTTPClientTransport],['/sse',SSEClientTransport]]){
   const c=new Client({name:'catalog-test',version:'1'});try{
    await c.connect(new T(new URL(path,f.origin)));const first=await c.listTools();assert.equal(first.tools.length,1);assert.equal(first.tools[0].name,'echo');assert.deepEqual(first.tools[0].inputSchema.required,['text']);assert.equal(first.tools[0].outputSchema.type,'object');assert.equal(first.nextCursor,'second');
    const second=await c.listTools({cursor:first.nextCursor});assert.deepEqual(second.tools.map(t=>t.name),['nested']);assert.equal(second.tools[0].inputSchema.properties.items.items.type,'object');assert.equal(second.nextCursor,undefined);
   }finally{await c.close();}
  }
  assert.equal(f.stats.toolsList,4);assert.equal(f.stats.httpToolsList,2);assert.equal(f.stats.sseToolsList,2);assert.ok(Object.values(f.stats).every(v=>typeof v==='number'));
 }finally{await f.close();}
});
